{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/hero-split-extras.json
    What HeroSplit shows under the lead: three figures in cards, a row of faces with a proof line, two small feature cards, or a quote with its author over three figures.
    Props (p): content, extra. -#}
{%- set v_content = (p.content ?? null) -%}
{%- set v_extra = (p.extra ?? 'none') -%}
{%- if ui_t(ui_eq(v_extra, 'stats')) %}
  {%- set c_4 -%}
    {%- for v_s in ui_l(ui_get(v_content, ['stats'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 3)) %}
        {%- set c_3 -%}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_s, ['value'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': '2xl', 'Weight': 'semibold'}, 'children': c_1}, with_context = false) }}
          {%- set c_2 -%}
            {{ ui_text(ui_get(v_s, ['label'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_2}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '0', 'Class': 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs': ui_attrs(['data-testid', 'hero-stat'])}, 'children': c_3}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/box/box.html.twig', {'p': {'Class': 'grid grid-cols-3 gap-4', 'Attrs': ui_attrs(['data-testid', 'hero-stats'])}, 'children': c_4}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_eq(v_extra, 'avatars')) %}
  {%- set c_7 -%}
    {%- set c_5 -%}
      {%- for v_p in ui_l(ui_get(v_content, ['people'])) %}
        {%- set v_i = loop.index0 -%}
        {%- if ui_t(ui_lt(v_i, 4)) %}
          {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_p, ['author']), 'ratio': '1/1', 'className': ui_cnv(['size-10 shrink-0 rounded-full'])}}, with_context = false) }}
        {%- endif %}
      {%- endfor %}
    {%- endset -%}
    {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Align': 'center'}, 'children': c_5}, with_context = false) }}
    {%- set c_6 -%}
      {{ ui_text(ui_get(v_content, ['proof'])) }}
    {%- endset -%}
    {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Class': 'text-muted-foreground'}, 'children': c_6}, with_context = false) }}
  {%- endset -%}
  {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'center', 'Class': 'flex-wrap', 'Attrs': ui_attrs(['data-testid', 'hero-proof'])}, 'children': c_7}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_eq(v_extra, 'minis')) %}
  {%- set c_13 -%}
    {%- for v_f in ui_l(ui_get(v_content, ['features'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 2)) %}
        {%- set c_12 -%}
          {%- set c_8 -%}
            {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s(ui_get(v_f, ['icon'])), 'Size': 20}}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/box/box.html.twig', {'p': {'Class': 'flex size-10 shrink-0 items-center justify-center rounded bg-muted'}, 'children': c_8}, with_context = false) }}
          {%- set c_11 -%}
            {%- set c_9 -%}
              {{ ui_text(ui_get(v_f, ['title'])) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_9}, with_context = false) }}
            {%- set c_10 -%}
              {{ ui_text(ui_get(v_f, ['text'])) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_10}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '0'}, 'children': c_11}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'start', 'Class': 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs': ui_attrs(['data-testid', 'hero-mini'])}, 'children': c_12}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/box/box.html.twig', {'p': {'Class': 'grid grid-cols-1 gap-4 sm:grid-cols-2', 'Attrs': ui_attrs(['data-testid', 'hero-minis'])}, 'children': c_13}, with_context = false) }}
{%- endif %}
{%- if ui_t(ui_eq(v_extra, 'quote')) %}
  {%- set c_24 -%}
    {%- for v_p in ui_l(ui_get(v_content, ['people'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 1)) %}
        {%- set c_19 -%}
          {%- set c_14 -%}
            {{ ui_text(ui_get(v_p, ['quote'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Tag': 'blockquote', 'Class': 'text-lg font-medium'}, 'children': c_14}, with_context = false) }}
          {%- set c_18 -%}
            {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_p, ['author']), 'ratio': '1/1', 'className': ui_cnv(['size-10 shrink-0 rounded-full'])}}, with_context = false) }}
            {%- set c_17 -%}
              {%- set c_15 -%}
                {{ ui_text(ui_get(v_p, ['author'])) }}
              {%- endset -%}
              {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_15}, with_context = false) }}
              {%- set c_16 -%}
                {{ ui_text(ui_get(v_p, ['role'])) }}
              {%- endset -%}
              {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_16}, with_context = false) }}
            {%- endset -%}
            {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '0'}, 'children': c_17}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'center'}, 'children': c_18}, with_context = false) }}
        {%- endset -%}
        {{ include('blocks/figure-block.html.twig', {'p': {'className': ui_cnv(['flex flex-col gap-4']), 'testid': 'hero-quote'}, 'children': c_19}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
    {%- set c_23 -%}
      {%- for v_s in ui_l(ui_get(v_content, ['stats'])) %}
        {%- set v_i = loop.index0 -%}
        {%- if ui_t(ui_lt(v_i, 3)) %}
          {%- set c_22 -%}
            {%- set c_20 -%}
              {{ ui_text(ui_get(v_s, ['value'])) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': '2xl', 'Weight': 'semibold'}, 'children': c_20}, with_context = false) }}
            {%- set c_21 -%}
              {{ ui_text(ui_get(v_s, ['label'])) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_21}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '0', 'Class': 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs': ui_attrs(['data-testid', 'hero-stat'])}, 'children': c_22}, with_context = false) }}
        {%- endif %}
      {%- endfor %}
    {%- endset -%}
    {{ include('ui/box/box.html.twig', {'p': {'Class': 'grid grid-cols-3 gap-4', 'Attrs': ui_attrs(['data-testid', 'hero-stats'])}, 'children': c_23}, with_context = false) }}
  {%- endset -%}
  {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '6', 'Align': 'stretch'}, 'children': c_24}, with_context = false) }}
{%- endif %}
